def write_byte(buffer, index, value):
    view = memoryview(buffer)
    unsigned = None
    try:
        if view.ndim != 1 or view.format not in ('B', 'b') or not view.c_contiguous:
            raise ValueError('one-dimensional contiguous byte buffer required')
        if view.readonly:
            raise ValueError('writable buffer required')
        if isinstance(index, bool) or not isinstance(index, int) or not 0 <= index < view.nbytes:
            raise IndexError('byte index out of range')
        if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= 255:
            raise ValueError('byte value out of range')
        if view.format == 'b':
            unsigned = view.cast('B')
            unsigned[index] = value
        else:
            view[index] = value
    finally:
        if unsigned is not None:
            unsigned.release()
        view.release()
```

原题知识说明：
缓冲协议允许对象暴露连续或非连续的内存视图供消费者访问，memoryview 可在支持的对象间减少复制。需注意格式、维度、读写权限和底层对象生命周期；它不是网络缓冲策略，也不保证所有操作零复制。

